package com.kiet13312.fishingchuxindiao;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;

/** Separate transparent components for the original Trương Tinh character. */
final class TruongTinhPartsAsset {
    private static Bitmap bitmap;
    static Bitmap load() {
        if (bitmap != null) return bitmap;
        try {
            byte[] data = Base64.decode(DATA, Base64.DEFAULT);
            bitmap = BitmapFactory.decodeByteArray(data, 0, data.length);
        } catch (Throwable ignored) { bitmap = null; }
        return bitmap;
    }
    private static final String DATA = "";
}
